code='''def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (7,)]
    if pts:
        r0,c0=pts[0]
        for r in range(r0+1,h):
            for c in range(w):
                if grid[r][c]==7 and abs(c-c0)<=r-r0: out[r][c]=3
    return out
''';open(p,'w').write(code);ans=runpy.run_path(p)['transform'](grid);print(ans)
